// filesChangedInCommit returns the set of file paths changed in a commit relative to its parent.
// For initial commits (no parent), all files in the commit tree are returned.
func filesChangedInCommit(repo *git.Repository, commit *object.Commit) map[string]struct{} {
	result := make(map[string]struct{})

	commitTree, err := commit.Tree()
	if err != nil {
		return result
	}

	var parentTree *object.Tree
	if commit.NumParents() > 0 {
		parent, err := commit.Parent(0)
		if err != nil {
			return result
		}
		parentTree, err = parent.Tree()
		if err != nil {
			return result
		}
	}

	// If no parent (initial commit), diff against empty tree
	if parentTree == nil {
		// All files in the commit tree are "changed"
		commitTree.Files().ForEach(func(f *object.File) error { //nolint:errcheck // best-effort
			result[f.Name] = struct{}{}
			return nil
		})
		return result
	}

	changes, err := parentTree.Diff(commitTree)
	if err != nil {
		return result
	}

	for _, change := range changes {
		name := change.To.Name
		if name == "" {
			name = change.From.Name
		}
		result[name] = struct{}{}
	}
	return result
}

// subtractFiles returns files from the input list that are NOT in the exclude set.
func subtractFiles(files []string, exclude map[string]struct{}) []string {
	var remaining []string
	for _, f := range files {
		if _, excluded := exclude[f]; !excluded {
			remaining = append(remaining, f)
		}
	}
	return remaining
}

